steps.solution:
terraform {
  backend "s3" {
    bucket  = "acme-tf-state"
    key     = "prod/terraform.tfstate"
    region  = "us-east-1"
    encrypt = true
  }
}

resource "aws_db_instance" "main" {
  identifier                  = "prod-db"
  engine                      = "postgres"
  instance_class              = "db.t3.medium"
  allocated_storage           = 50
  username                    = "dbadmin"
  manage_master_user_password = true
  deletion_protection         = true

  lifecycle {
    prevent_destroy = true
  }
}
